  'batch_translation_beta': 'ಬ್ಯಾಚ್ ಅನುವಾದ (ಬೀಟಾ)',
  'batch_timeout_log': 'ಟೈಮ್‌ಔಟ್ ಮೀರಿದೆ, ಮುಂದಿನ ಫೈಲ್‌ಗೆ ಸ್ಕಿಪ್ ಆಗುತ್ತಿದೆ.',
  'batch_process_completed': 'ಬ್ಯಾಚ್ ಪ್ರಕ್ರಿಯೆ ಮುಗಿದಿದೆ.',
  'tour_add_file_title': 'ಉಪಶೀರ್ಷಿಕೆ ಫೈಲ್ ಸೇರಿಸಿ',
  'tour_add_file_desc':
      'ನೀವು ಅನುವಾದಿಸಲು ಬಯಸುವ SRT ಅಥವಾ VTT ಫೈಲ್‌ಗಳನ್ನು ಇಲ್ಲಿ ಸೇರಿಸಬಹುದು.\nನಿಮ್ಮ ಸಾಧನ, Google Drive, Dropbox ಅಥವಾ Yandex Disk ನಿಂದ ನೀವು ಒಂದೇ ಸಮಯದಲ್ಲಿ ಬಹು ಫೈಲ್‌ಗಳನ್ನು ಆಯ್ಕೆ ಮಾಡಬಹುದು.',
  'tour_cloud_sources_label': 'Google Drive / Dropbox / Yandex',
  'tour_language_title': 'ಗುರಿ ಭಾಷೆಯನ್ನು ಹೊಂದಿಸಿ',
  'tour_language_desc':
      'ನಿಮ್ಮ ಫೈಲ್‌ಗಳನ್ನು ನೀವು ಯಾವ ಭಾಷೆಗೆ ಅನುವಾದ ಮಾಡಲು ಬಯಸುತ್ತೀರಿ ಎಂಬುದನ್ನು ಆರಿಸಿ. AI ಉಪಶೀರ್ಷಿಕೆಗಳ ಅರ್ಥವನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳುತ್ತದೆ ಮತ್ತು ಆ ಭಾಷೆಗೆ ಅತ್ಯಂತ ನಿಖರವಾದ ಅನುವಾದವನ್ನು ಒದಗಿಸುತ್ತದೆ.',
  'tour_translate_title': 'ಅನುವಾದವನ್ನು ಪ್ರಾರಂಭಿಸಿ',
  'tour_translate_desc':
      'ನಿಮ್ಮ ಸಾಧನದಲ್ಲಿ ಒಂದು ಫೈಲ್ ಅಥವಾ ಆಯ್ದ ಪಟ್ಟಿಯನ್ನು ಅನುಕ್ರಮವಾಗಿ ಅನುವಾದಿಸಲು ನೀವು ಈ ಬಟನ್ ಬಳಸಬಹುದು. ಅನುವಾದ ಪ್ರಕ್ರಿಯೆಯನ್ನು ನೇರವಾಗಿ ಟ್ರ್ಯಾಕ್ ಮಾಡಬಹುದು.',
  'tour_batch_translate_title': 'ಬ್ಯಾಚ್ ಅನುವಾದ (Batch API)',
  'tour_batch_translate_desc':
      'ನೀವು ಬಹು ಫೈಲ್‌ಗಳನ್ನು ಅನುವಾದಿಸುತ್ತಿದ್ದರೆ ಇದು ಶಿಫಾರಸು ಮಾಡಲಾದ ವಿಧಾನವಾಗಿದೆ. ನಿಮ್ಮ ಫೈಲ್‌ಗಳನ್ನು ಸರ್ವರ್‌ಗೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ನೀವು ಅಪ್ಲಿಕೇಶನ್ ಅನ್ನು ಮುಚ್ಚಿದರೂ ಹಿನ್ನೆಲೆಯಲ್ಲಿ ಅನುವಾದವು ಸುರಕ್ಷಿತವಾಗಿ ಪೂರ್ಣಗೊಳ್ಳುತ್ತದೆ. ಅದು ಪೂರ್ಣಗೊಂಡಾಗ ನಿಮಗೆ ಸೂಚಿಸಲಾಗುತ್ತದೆ.',
  'tour_batch_translate_title_new': 'ಹೊಸ ವಿಧಾನ: ಬ್ಯಾಚ್ ಅನುವಾದ (Batch API) 🎉',
  'tour_batch_translate_desc_new':
      'ಬಹು ಫೈಲ್‌ಗಳನ್ನು ಅನುವಾದಿಸುವಾಗ ನೀವು ಇನ್ನು ಮುಂದೆ ಅಪ್ಲಿಕೇಶನ್ ಅನ್ನು ತೆರೆದಿರುವ ಅಗತ್ಯವಿಲ್ಲ!\n\nನಿಮ್ಮ ಎಲ್ಲಾ ಫೈಲ್‌ಗಳನ್ನು ಒಂದೇ ಬಾರಿಗೆ ಸರ್ವರ್‌ಗೆ ಕಳುಹಿಸಿ ಮತ್ತು ಅವುಗಳನ್ನು ಹಿನ್ನೆಲೆಯಲ್ಲಿ ಸುರಕ್ಷಿತವಾಗಿ ಅನುವಾದಿಸಲು ಬಿಡಿ. ಪ್ರಕ್ರಿಯೆ ಮುಗಿದ ನಂತರ ನೀವು ಅಧಿಸೂಚನೆಯನ್ನು ಸ್ವೀಕರಿಸುತ್ತೀರಿ.',
  'tour_welcome_title': 'ಸ್ವಾಗತ ಉಡುಗೊರೆ 🎁',
  'tour_welcome_desc':
      '5 ಕ್ರೆಡಿಟ್‌ಗಳ ಸ್ವಾಗತ ಉಡುಗೊರೆಯಾಗಿ ನಿಮ್ಮ ಖಾತೆಗೆ ಸೇರಿಸಲಾಗಿದೆ! ನೀವು ಇಲ್ಲಿ ನಿಮ್ಮ ಕ್ರೆಡಿಟ್ ಬ್ಯಾಲೆನ್ಸ್ ಅನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಬಹುದು ಅಥವಾ ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಹೆಚ್ಚಿನದನ್ನು ಸೇರಿಸಬಹುದು. Sign in with your Google account to get +2 extra credits!',
